const payload = $input.first().json;
const yield10Y = payload.yield10Y || 4.15;
const yield2Y = payload.yield2Y || 3.95;
const spread10Y2Y = Math.round((yield10Y - yield2Y) * 100) / 100;
const cpiInflation = payload.cpi || 2.9;
const fedFundsRate = payload.fedFunds || 5.25;
const dxy = payload.dxy || 101.4;

// 4-Quadrant classification
let regime = 'Goldilocks';
let riskPosture = 'RISK_ON';

if (cpiInflation < 3.2 && spread10Y2Y > 0) {
  regime = 'Goldilocks';
  riskPosture = 'AGGRESSIVE_RISK_ON';
} else if (cpiInflation >= 3.5 && spread10Y2Y > 0) {
  regime = 'Reflation';
  riskPosture = 'COMMODITIES_TILT';
} else if (cpiInflation >= 3.5 && spread10Y2Y <= 0) {
  regime = 'Stagflation';
  riskPosture = 'MAX_DEFENSIVE';
} else {
  regime = 'Contraction';
  riskPosture = 'TREASURIES_CASH';
}

return {
  json: {
    regime,
    riskPosture,
    spread10Y2Y,
    cpiInflation,
    fedFundsRate,
    dxy,
    equityTilt: regime === 'Goldilocks' ? 'Overweight' : 'Neutral',
    cryptoTilt: regime === 'Goldilocks' ? 'Overweight' : 'Neutral'
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'macro-regime',
    botName: 'Macroeconomic Regime & Fed Watchdog',
    regimeSummary: text,
    timestamp: new Date().toISOString()
  }
};
